SELECT e.Fname, e.Minit, e.Lname, e.Ssn
FROM employee e
WHERE e.Fname IN (SELECT d.Dependent_name FROM dependent d);

SELECT DISTINCT e.Fname, e.Minit, e.Lname, e.Ssn
FROM employee e
JOIN dependent d ON e.Fname = d.Dependent_name;

SELECT p.Pname AS Project,
       e.Fname || ' ' || e.Minit || ' ' || e.Lname AS EmployeeFullName
FROM project p
JOIN employee e ON (
    TRIM(
        SUBSTR(
            e.Address,
            INSTR(e.Address, ',') + 1,
            INSTR(SUBSTR(e.Address, INSTR(e.Address, ',') + 1), ',') - 1
        )
    ) = p.Plocation
);
